const result = document.querySelector('#result');
const summary = document.querySelector('#summary');
const list = document.querySelector('#list');

const courses = [
  { title: '자바스크립트 입문', hours: 12 },
  { title: '리액트 시작하기', hours: 20 },
  { title: 'CSS 레이아웃 마스터', hours: 8 },
];

// 결과 영역은 원래 초점을 받지 않습니다. 코드로 보낼 수 있게 표시해 둡니다.
result.setAttribute('tabindex', '-1');

const render = (items) => {
  summary.textContent = `코스 ${items.length}개`;
  list.innerHTML = items.map((course) => `<li>${course.title} · ${course.hours}시간</li>`).join('');
};

render(courses);

document.querySelector('#short').addEventListener('click', () => {
  render(courses.filter((course) => course.hours <= 12));
  result.focus();
  console.log('지금 초점:', document.activeElement.tagName, document.activeElement.id);
});

